-space:nowrap}.badge-case-count strong span{font-size:22px;color:var(--journal-muted)}.badge-case-count small{display:block;font-size:11px;color:var(--journal-muted)}.badge-case-track{height:5px;background:var(--journal-border);margin:22px 0 24px;border-radius:8px;overflow:hidden}.badge-case-track span{display:block;height:100%;background:var(--journal-progress);border-radius:inherit}.badge-case-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.badge-case-slot{position:relative;min-width:0;padding:14px;background:var(--journal-soft);border:1px solid var(--journal-border);border-radius:14px;text-align:center}.badge-case-slot.is-earned{background:var(--journal-card);border-color:#9bb8cf;box-shadow:inset 0 3px 0 #adc9df}.badge-case-slot-top{display:flex;align-items:center;justify-content:space-between;gap:4px;text-align:left;font-size:9px;color:var(--journal-muted)}.badge-case-slot-top>span:first-child{font-variant-numeric:tabular-nums;letter-spacing:.1em}.badge-case-status{white-space:nowrap}.is-earned .badge-case-status{color:var(--journal-accent)}.badge-case-display{display:flex;justify-content:center;padding:15px 0 12px}.badge-case-slot:not(.is-earned) .badge-case-display{filter:grayscale(1);opacity:.37}.badge-case-slot h4{margin:0;color:var(--journal-heading);font-size:14px;font-weight:600;overflow-wrap:anywhere}.badge-case-place{margin:6px 0 0;font-size:11px;color:var(--journal-muted)}.badge-case-caption{margin:11px 0 0;font-size:10px;line-height:1.5;color:var(--journal-muted)}.badge-case-footer{flex:none;display:flex;align-items:center;gap:9px;padding:15px 24px;border-top:1px solid var(--journal-border);background:var(--journal-soft);color:var(--journal-muted);font-size:10px;line-height:1.5}.badge-case-footer>.journal-icon{width:16px;height:16px}.badge-case-state{padding:40px 12px;text-align:center;color:var(--journal-muted)}
